if($_SERVER['REQUEST_METHOD']==='POST'){checkCsrf();try{$q=$pdo->prepare('SELECT email,password_hash FROM admins WHERE id=?');$q->execute([$_SESSION['admin_id']]);$owner=$q->fetch();require_once dirname(__DIR__).'/private/platform.php';if(!$owner||!gszLoginAttempt('connections:'.$owner['email'],(string)($_SERVER['REMOTE_ADDR']??''))||!password_verify((string)($_POST['owner_password']??''),$owner['password_hash']))throw new RuntimeException('Dein Zentrale-Passwort stimmt nicht (zur Sicherheit bei Änderungen am Postfach nötig).');gszLoginAttempt('connections:'.$owner['email'],(string)($_SERVER['REMOTE_ADDR']??''),true);$action=(string)($_POST['action']??'');
