 elseif($action==='probe'){$probe=gszSetupMailProbe(gszLoadConfig());$_SESSION['mail_probe']=['imap'=>$probe['imap']['status'],'smtp'=>$probe['smtp']['status'],'message'=>$probe['imap']['message']??($probe['smtp']['message']??'')];if($probe['status']==='PASS'&&empty($config['mail_sent_folder']))gszManagedSave(array_filter($probe['recommended_folders']));$_SESSION['app_notice']=$probe['status']==='PASS'?'Verbindung in Ordnung: Empfang und Versand-Anmeldung funktionieren. Es wurde keine Mail gesendet.':'Verbindung nicht in Ordnung – Details oben.';}
 elseif($action==='send_release'){if(empty($_POST['confirm_send_release']))throw new RuntimeException('Bitte bestätigen.');if(empty(gszLoadConfig()['mail_sent_folder']))throw new RuntimeException('Erst „Verbindung testen“, damit der Gesendet-Ordner erkannt wird.');gszManagedSave(['allow_mail_send'=>true]);$_SESSION['app_notice']='Versand freigeschaltet. Jede Mail wird weiterhin erst nach deiner Bestätigung gesendet.';}
 elseif($action==='delete'){if(empty($_POST['confirm_delete']))throw new RuntimeException('Bitte das Löschen bestätigen.');gszMailCredentialDelete();unset($_SESSION['mail_probe']);$_SESSION['app_notice']='Postfachzugang gelöscht. Mail ist ausgeschaltet; vorhandene Nachrichten bleiben in der Zentrale.';}
 else throw new RuntimeException('Aktion unbekannt.');
 }catch(Throwable $e){$_SESSION['app_error']=$e instanceof PDOException?'Speichern nicht möglich.':(str_starts_with($e->getMessage(),'GSZ_')?'Die geschützte Ablage auf dem Server ist nicht beschreibbar. Bitte Systemstatus öffnen.':$e->getMessage());}redirect('connections.php');}
$stored=gszMailCredentialExists();$blocked=gszMailAuthBlockedNow();$state=gszMailAuthState();$enabled=filter_var($config['mail_enabled']??false,FILTER_VALIDATE_BOOLEAN);$probe=$_SESSION['mail_probe']??null;
$pw=static fn()=>'<label>Dein Zentrale-Passwort (Bestätigung)<input type="password" name="owner_password" autocomplete="current-password" required></label>';
