<section class="card"><h2><?=$blocked?'Passwort abgelehnt':($stored&&$enabled?'Postfach verbunden':'Noch nicht eingerichtet')?></h2>
<p><?php if($blocked):?>Das Postfach hat das gespeicherte Passwort am <?=e((new DateTimeImmutable($state['at']??'now'))->setTimezone(new DateTimeZone('Europe/Berlin'))->format('d.m.Y, H:i'))?> Uhr abgelehnt. Bis du es neu einträgst, versucht die Zentrale keine weitere Anmeldung – so wird das Postfach nicht gesperrt.<?php elseif($stored&&$enabled):?><?=e((string)$config['mail_user'])?> · Passwort sicher gespeichert. Abruf, Lesen und Senden funktionieren ohne erneute Eingabe.<?php else:?>Trage Postfachadresse und Passwort einmal ein. Danach fragt die Zentrale nicht mehr danach.<?php endif?></p>
<?php if($probe):?><p class="<?=$probe['imap']==='PASS'&&$probe['smtp']==='PASS'?'notice':'error'?>">Empfang: <?=$probe['imap']==='PASS'?'in Ordnung':'nicht in Ordnung'?> · Versand-Anmeldung: <?=$probe['smtp']==='PASS'?'in Ordnung':'nicht in Ordnung'?><?=$probe['message']&&($probe['imap']!=='PASS'||$probe['smtp']!=='PASS')?' – '.e($probe['message']):''?></p><?php endif?></section>
<details class="card"<?=(!$stored||$blocked)?' open':''?>><summary><?=$stored?'Passwort oder Postfach ändern':'Postfach eintragen'?></summary><form method="post"><?php gszFields('mail');?><label>Postfachadresse<input type="email" name="mail_user" value="<?=e((string)($config['mail_user']?:'info@gebaeudeservice-zentrum.de'))?>" required autocomplete="username"></label><label>Postfach-Passwort<?=$stored?' (leer lassen = unverändert)':''?><input type="password" name="mail_pass" autocomplete="new-password" <?=$stored?'':'required'?>></label><label>Signatur<textarea name="mail_signature" maxlength="5000"><?=e((string)$config['mail_signature'])?></textarea></label><?php foreach(['mail_sent_folder','mail_trash_folder','mail_archive_folder'] as $k):?><input type="hidden" name="<?=e($k)?>" value="<?=e((string)$config[$k])?>"><?php endforeach?><?=$pw()?><button class="primary">Speichern</button></form><p class="hint">STRATO: Empfang imap.strato.de (993), Versand smtp.strato.de (465), beides verschlüsselt. Das Passwort wird nur verschlüsselt außerhalb des Webbereichs gespeichert und nie angezeigt.</p></details>
<?php if($stored):?><details class="card"><summary>Verbindung testen</summary><p class="hint">Meldet sich einmal an Empfang und Versand an. Es wird keine Mail gesendet.</p><form method="post"><?php gszFields('probe');?><?=$pw()?><button>Jetzt testen</button></form></details>
<?php if(empty($config['allow_mail_send'])):?><details class="card"><summary>Senden freischalten</summary><form method="post"><?php gszFields('send_release');?><label><input type="checkbox" name="confirm_send_release" value="1" required> Senden erlauben. Jede Mail wird trotzdem erst nach meiner Bestätigung verschickt.</label><?=$pw()?><button>Senden freischalten</button></form></details><?php endif?>
<details class="card"><summary>Zugang löschen</summary><form method="post"><?php gszFields('delete');?><label><input type="checkbox" name="confirm_delete" value="1" required> Gespeichertes Postfach-Passwort vom Server löschen und Mail ausschalten</label><?=$pw()?><button class="danger">Zugang löschen</button></form></details><?php endif?>
